///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        gform.scroll = "no";
        // dts_leadcom.dataid ="menu.csv";
        // dts_leadcom.dataid ="../service/ui/JUI103_S01.jsp";
        // dts_leadcom.reset();
        if (js_market === "6") {
            $c.cm.setColumnProp(grd_leadcom, "TEXT", "Name", "지정자문인명");
            $c.cm.setColumnProp(grd_selectleadcom, "TEXT", "Name", "지정자문인명");
        }
        await scwin.listSync();
        dts_leadcom.sort("+TEXT", 0);
        // dts_leadcom.sort(); // W-Craft 주석처리
        const vHeadString = "VALUE:STRING(9),TEXT:STRING(100)";
        // dts_selectleadcom.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인

        // dts_selectleadcom.addRow();
        scwin.oldadd();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05013.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name grd_leadcom_OnDblClick
 * @description grd_leadcom 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_leadcom_OnDblClick = function(row, colid) {
    try {
        scwin.add();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05013.grd_leadcom_OnDblClick" });
    }
};

/**
