/**
 * @method
 * @name gform_bak_onload
 * @description gform_bak onload 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.gform_bak_onload = function() {
    try {
        gform.scroll = "no";
        // dts_leadcom.dataid ="menu.csv";
        dts_leadcom.dataid = "../service/ui/JUI103_S01.jsp";
        dts_leadcom.reset();
        dts_leadcom.sort("+PAGE_TEXT", 0);
        // dts_leadcom.sort(); // W-Craft 주석처리

        //    var vHeadString="PAGE_VALUE:STRING(9),PAGE_TEXT:STRING(20)";
        //    dts_selectleadcom.SetDataHeader(vHeadString);

        dts_selectleadcom.dataid = "../service/ui/JUI200_S01.jsp";
        dts_selectleadcom.reset();
        // alert(dts_selectleadcom.dataid);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05013.gform_bak_onload" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name listSync
 * @description list Sync 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync = async function() {
    if (js_market === "6") {
        let url;
        const sbmOptions = {
            id : "sbm_dts_leadcom",
            action : "/listingCommon.do",
            ref : "",
            target : "dts_leadcom=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    } else {
        // 상장주선인
        const sbmOptions = {
            id : "sbm_dts_leadcom",
            action : "/CodeAction.do",
            ref : "",
            target : "dts_leadcom=body.content",
            isProcessMsg : false
        };

        const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
        // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    }
    dts_leadcom.setBroadcast(false);
    for (k = 1; k <= dts_leadcom.getRowCount(); k++) {
        if (dts_leadcom.getCellData(k, "TEXT") === "") {
            // 널값은 삭제
            dts_leadcom.removeRow(k);
        }
    }
    dts_leadcom.setBroadcast(true, true);
    // alert("call");

};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name oldadd
 * @description oldadd 처리
 * @returns {void}
 * @hidden N
 */
scwin.oldadd = function() {
    let arrOldValues = new Array();
    let vValue;
    let vText;
    const fr_getLead = $c.frame.path("../").fn_getLeadComNoStr;
    // alert("lead :"+lead.text);
    const vleadnm = fr_getLead();
    // alert("[vleadnm] :"+vleadnm);
    if (vleadnm !== undefined) {
        arrOldValues = vleadnm.split(",");
    }
    // alert("arrOldValues :"+arrOldValues);

    dts_selectleadcom.setBroadcast(false);
    for (let i = 0; i < arrOldValues.length; i++) {
        // arr배열의 length만큼 반복
        // alert("old :" +arrOldValues[i]+"\n");  //브라우져에 배열의 요소를 순서대로 찍는다.
        for (k = 1; k <= dts_leadcom.getRowCount(); k++) {
            if (dts_leadcom.getCellData(k, "TEXT") === arrOldValues[i]) {
                // alert("dts_leadcom :"+ dts_leadcom.NameValue(k, "TEXT") + " arrOldValues: " +arrOldValues[i]+"\n");  //브라우져에 배열의 요소를 순서대로 찍는다.
                vValue = dts_leadcom.getCellData(k, "VALUE");
                vText = dts_leadcom.getCellData(k, "TEXT");
                let RowPosition = dts_selectleadcom.getRowCount();
                dts_selectleadcom.insertRow();
                dts_selectleadcom.setCellData(RowPosition + 1, "VALUE", vValue);
                dts_selectleadcom.setCellData(RowPosition + 1, "TEXT", vText);
            }
        }
    }
    dts_selectleadcom.setBroadcast(true, true);
};

/**
 * @method
 * @name add
 * @description add 처리
 * @returns {void}
 * @hidden N
 */
scwin.add = function() {
    let vValue = dts_leadcom.getCellData(dts_leadcom.getRowPosition(), "VALUE");
    let vText = dts_leadcom.getCellData(dts_leadcom.getRowPosition(), "TEXT");
    let RowPosition = dts_selectleadcom.getRowCount();
    for (i = 1; i <= dts_selectleadcom.getRowCount(); i++) {
        if (dts_selectleadcom.getCellData(i, "VALUE") === vValue) {
            return;
        }
    }
    dts_selectleadcom.insertRow();
    dts_selectleadcom.setCellData(RowPosition + 1, "VALUE", vValue);
    dts_selectleadcom.setCellData(RowPosition + 1, "TEXT", vText);
};

/**
 * @method
 * @name del
 * @description del 처리
 * @returns {void}
 * @hidden N
 */
scwin.del = function() {
    // var RowPos = dts_selectleadcom.ValueRow(dts_selectleadcom.RowPosition, MTr_2.ItemText);
    const RowPos = dts_selectleadcom.getRowPosition();
    dts_selectleadcom.removeRow(RowPos);
};

/**
 * @method
 * @name confirm
 * @description confirm 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.confirm = async function() {
    let vValue;
    let vText;
    for (i = 1; i <= dts_selectleadcom.getRowCount(); i++) {
        if (i === 1) {
            vValue = dts_selectleadcom.getCellData(i, "VALUE");
            vText = dts_selectleadcom.getCellData(i, "TEXT");
        } else {
            vValue = vValue + "," + dts_selectleadcom.getCellData(i, "VALUE");
            vText = vText + "," + dts_selectleadcom.getCellData(i, "TEXT");
        }
    }

    // alert("vText :"+vText);
    const fr_setLead = $c.frame.path("../").fn_setLeadComNMStr;
    fr_setLead(vValue, vText);
    await $c.win.closePopup();
};
